import type { FieldValue, Program, Provenance } from '../lib/types'

const ACC = '2026-09-13'
function prov(source_url: string, source_title: string, source_type: Provenance['source_type'], verification: Provenance['verification'], notes?: string, language: Provenance['language'] = 'en'): Provenance {
  return { source_url, source_title, source_type, accessed_date: ACC, language, verification, notes }
}
function fv<T>(value: T | null, scope: FieldValue<T>['scope'], p?: Provenance, unknown_label?: FieldValue<T>['unknown_label']): FieldValue<T> {
  return p ? { value, scope, provenance: p, ...(unknown_label ? { unknown_label } : {}) } : { value, scope, ...(unknown_label ? { unknown_label } : {}) }
}
